const {
  DydxClient,
  Asset,
  Market,
  OrderSide,
  OrderType,
  TimeInForce,
  PositionStatus,
} = require('@dydxprotocol/v3-client')
const Web3 = require('web3')

const HTTP_HOST = 'https://api.dydx.exchange'

const ccxt = require('ccxt')
